sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var header = request.body.data.HEADER || {};
        var payload = request.body.data.PAYLOAD || {};
        var source = header.source,
            eventType = header.eventtype;

        var isSWB = (source === 'SMARTWORKBENCH' && eventType === 'SMARTWORKBENCH_TSD_CASH');
        var isSTS = (source === 'STS' && eventType === 'STS_TSD_CASH');
        var isITM = (source === 'ITM');
        var isMRD = (source === 'MRD' && header.objectidtype === 'MRD_ID');

        if (!(isSWB || isSTS || isITM || isMRD)) {
            response.setBody([]);
            return;
        }

        // Duplicate check ONLY on message_id
        var widgetInbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
        widgetInbound.addQuery('message_id', header.messageid);
        widgetInbound.query();
        if (widgetInbound.next()) {
            throw {
                message: 'Duplicate Entry.',
                failureDescription: 'Duplicate entry for message_id: ' + header.messageid
            };
        }

        var utils = new x_hsb11_mss_tsd.MSS_Treasury_Utils();
        // ITM closed-complete Treasury case check
        if (isITM) {
            var closedCaseId = utils.isClosedCompleteITMTreasuryCase(payload);
            if (closedCaseId) {
                throw {
                    message: 'Duplicate sys_id.',
                    failureDescription: 'ITM Treasury case already Updated (Duplicate sys_id). sys_id=' + closedCaseId
                };
            }
        }

        var out = utils.insertInboundWidgetRecord(header, payload);
        response.setBody(out);

    } catch (e) {
        var failureDescription = e.failureDescription ||
            'Scripted REST API Resource - el_inbound_event_treasury: Unknown exception while processing Treasury Request. Name: ' + e.name + ', Message: ' + e.message;
        gs.error(failureDescription);
        new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeTreasury_EventInbound');
        response.setError(new sn_ws_err.BadRequestError(e.message || 'Processing error.'));
        response.setStatus(400);
    }
})(request, response);
